import java.util.Arrays;
import java.util.Collections;

public List<List<Integer>> permute(int[] nums) {
    ArrayList<List<Integer>> result = new ArrayList<>();
    // Sort the array to make it easier to find permutations
    Arrays.sort(nums);
    backtrack(result, nums, new ArrayList<>());
    return result;
}

private void backtrack(ArrayList<List<Integer>> result, int[] nums, ArrayList<Integer> current) {
    if (current.size() == nums.length) { // If the current permutation is complete
        result.add(new ArrayList<>(current));
        return;
    }

    for (int i = 0; i < nums.length; i++) {
        if (current.contains(nums[i])) continue; // Skip already used elements
        current.add(nums[i]); // Add the current element to the permutation
        backtrack(result, nums, current); // Recur for the remaining elements
        current.remove(current.size() - 1); // Backtrack and remove the last element added
    }
}
