import java.util.Map;
import java.util.HashMap;
import java.util.stream.Collectors;

public class Solution {
    /**
     * Counts how many items in the list are twice some other item in the list.
     *
     * @param numbers The array of integers.
     * @return The count of items in the list that are twice some other item.
     */
    public static int countDoubles(int[] numbers) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int num : numbers) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }
        return (int) counts.entrySet().stream()
                .filter(entry -> entry.getValue() >= 2)
                .mapToInt(Map.Entry::getKey)
                .filter(num -> counts.getOrDefault(num / 2, 0) >= 1)
                .count();
    }

    public static void main(String[] args) {
        // Test cases
