    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    int denominator = word1.length() + word2.length() - commonLetters;
    if (denominator == 0) {
        return "The denominator is zero, cannot calculate the fraction.";
    }

    int num = commonLetters;
    int GCD = gcd(num, denominator);
    num /= GCD;
    denominator /= GCD;

    return "appx(" + word1 + ", " + word2 + ") = " + num + "/" + denominator;
}

// Helper method to calculate the greatest common divisor
private static int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
