import java.util.*;

public class AppleCollector {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        // Build the adjacency list for the tree
        HashMap<Integer, List<Integer>> adjacencyList = new HashMap<>();
        for (int i = 0; i < edges.length; i++) {
            int u = edges[i][0], v = edges[i][1];
            adjacencyList.computeIfAbsent(u, k -> new ArrayList<>()).add(v);
            adjacencyList.computeIfAbsent(v, k -> new ArrayList<>()).add(u);
        }

        // Helper function to recursively calculate the total time
        return helper(adjacencyList, hasApple, 0, -1);
    }

    private int helper(HashMap<Integer, List<Integer>> adjacencyList, boolean[] hasApple, int currentNode, int parent) {
        int totalTime = 0;
        if (parent != -1 && hasApple[parent]) {
            totalTime += 2; // Time to go back and return
        }

        int additionalTime = 0;
        for (int neighbor : adjacencyList.getOrDefault(currentNode, Collections.emptyList())) {
            if (neighbor != parent) {
                additionalTime += helper(adjacencyList, hasApple, neighbor, currentNode);
            }
        }

        return additionalTime + totalTime;
    }

