        }

        for (int[] edge : edges) {
            graph.get(edge[0]).add(edge[1]);
            graph.get(edge[1]).add(edge[0]);
        }

        helper(0, hasApple);
        return time;
    }

    public void helper(int index, boolean[] hasApple) {
        time++;
        apple = hasApple[index];
        List<Integer> children = graph.get(index);
        for (int child : children) {
            if (!apple && !helper(child, hasApple)) continue;
            time++;
        }
    }
