    for (int i = 29; i >= 2; i--) {
        if (fibSeq[i] <= k) {
            pq.offer(fibSeq[i]);
        }
    }

    int count = 0;
    while (!pq.isEmpty() && k > 0) {
        if (k >= pq.peek()) {
            k -= pq.poll();
            count++;
        } else {
