        Scanner sc = new Scanner(System.in);
        System.out.print("Enter an integer k: ");
        int k = sc.nextInt();
        sc.close();

        int result = sol.findMinFibonacciNumbers(k);
        System.out.println("Minimum number of Fibonacci numbers: " + result);
    }
}
