public static int findSmallestInteger(int n) {
    // Convert the input integer to a character array
    char[] digits = String.valueOf(n).toCharArray();

    // Initialize the smallest integer found
    int smallest = Integer.MAX_VALUE;

    // Try all possible permutations of the digits
    for (int perm = 1; perm <= factorial(digits.length); perm++) {
        // Calculate the next permutation
        char nextPerm[] = nextPermutation(digits, perm);

        // Check if the new permutation is greater than the starting integer n
        if (nextPerm != null && Long.parseLong(new String(nextPerm)) > n) {
            // Found a smaller positive integer, update the smallest
            smallest = Math.min(smallest, Long.parseLong(new String(nextPerm)));
        }
    }

    // Return -1 if no such permutation exists
    return smallest == Integer.MAX_VALUE ? -1 : smallest;
}

private static char[] nextPermutation(char[] digits, int pos) {
    // Find the first element that is smaller than its successor
    for (int i = pos - 1; i > 0; i--) {
        if (digits[i] < digits[i - 1]) {
            // Find the smallest element in the suffix that is larger than digits[i - 1]
            for (int j = pos; j <= digits.length; j++) {
                if (digits[j] > digits[i - 1]) {
                    // Swap digits[i - 1] and digits[j]
                    char temp = digits[i - 1];
                    digits[i - 1] = digits[j];
                    digits[j] = temp;

                    // Reverse the suffix starting from index i
                    for (int k = 0; k < (digits.length - i) / 2; k++) {
                        char temp = digits[i + k];
                        digits[i + k] = digits[digits.length - (k + 1)];
                        digits[digits.length - (k + 1)] = temp;
                    }

                    // Return the new permutation
                    return digits;
                }
            }
        }
    }

    // Return null if no permutation can be formed
    return null;
}

private static int factorial(int n) {
    int result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;
    }
    return result;
}
