import java.util.List;

public class LexicalOrder {
    public List<Integer> lexicalOrder(int n) {
        if (n == 0) {
            return new LinkedList<>();
        }

        LinkedList<Integer> list = new LinkedList<>();
        visited.add(1);
        list.add(1);

        int stack = Integer.valueOf(1);

        while (!list.isEmpty() || stack != 0) {
            while (stack > 0) {
                int node = stack % 10;
                if (node >= n) {
                    break;
                }
                list.add(node);
                stack *= 10;
            }
            if (list.isEmpty()) {
                break;
            }
            int nodeIndex = list.size() - 1;
            list.add(list.remove(nodeIndex) * 10 + 9);
            stack = list.get(list.size() - 1);
            stack -= 10;
            visited.add(list.get(list.size() - 1));
        }

        return list;
    }
    private static LinkedList<Integer> visited;
}
