            generateLimo(i, 0, result, digits);
        }

        return result;
    }

    private void generateLimo(int number, int position, List<Integer> result, char[] digits) {
        if (position == digits.length) {
            result.add(Integer.parseInt(String.valueOf(digits)));
            return;
        }

        for (int i = 0; i < 10; i++) {
            digits[position] = (char) ('0' + i);
            generateLimo(number, position + 1, result, digits);
            if (number == 9) {
                break;
            }
        }
    }

