import java.util.Scanner;

public class WordReverser {

    /**
     * Reverses each word in the sentence while maintaining the original word order.
     *
     * @param sentence The sentence to reverse the words in.
     * @return A string with each word reversed, but in the original order.
     */
    public static String reverseWords(String sentence) {
        StringBuilder reversedSentence = new StringBuilder();

        for (String word : sentence.split(" ")) {
            StringBuilder reversedWord = new StringBuilder();
            for (int i = word.length() - 1; i >= 0; i--) {
                reversedWord.append(word.charAt(i));
            }
            reversedSentence.append(reversedWord.toString());
            reversedSentence.append(" ");
        }

        // Trim the last space and return the result
        return reversedSentence.toString().replaceAll("( )+", " ").trim();
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter a sentence to reverse the words:");
        String sentence = scanner.nextLine();
        scanner.close();

        String reversedSentence = reverseWords(sentence);
        System.out.println("Reversed sentence: " + reversedSentence);
    }
}
